    "officialAnswerNumber": 4,
    "explanation": "原点での空間と時間の傾きが同符号なので、波は負方向に進む。波長12 m、周期6 sより速さは2 m/sで、求める変位は初期波形のx＝10 m、すなわちx＝−2 mの約−0.9 mである。",
    "choiceExplanations": {
      "ア": "変位の符号と大きさは合っている。原点で空間と時間の両方のグラフが右上がりなので、波形は負方向へ動く。",
      "イ": "正方向へ進む波では、原点における二つのグラフの傾きが逆符号になる。実際は同符号であり、求める点は変位0の位相にも一致しない。",
      "ウ": "二つのグラフから求めた速さ2 m/sで負方向へ進むため、もとの波形のx＝10 mを読む。周期性でx＝−2 mの点と同じになり、変位は負である。",
      "エ": "原点での空間と時間の傾きが同符号なので、波は負方向に進む。波長12 m、周期6 sより速さは2 m/sで、求める変位は初期波形のx＝10 m、すなわちx＝−2 mの約−0.9 mである。",
      "オ": "伝播方向は負で合っているが、x＝2 mで変位が0なのは初期時刻である。4秒後には波形が8 m移動している。"
    },
