    "question": "科学技術の動向等に関する記述㋐、㋑、㋒のうち、妥当なもののみを全て挙げているのはどれか。\n㋐　ムーンショット型研究開発制度とは、超高齢化社会や地球温暖化問題などの重要な社会課題に対し、人々を魅了する野心的な目標及び構想を国が策定し、我が国発の破壊的イノベーションの創出を目指し、従来技術の延長にない、より大胆な発想に基づく挑戦的な研究開発を推進する制度のことである。\n㋑　説明可能なAI（XAI）とは、機械学習を用いたAIの意思決定プロセスを、人間が理解可能な形で説明できるようにしたAIのことである。説明可能なAIは、既に医療や建設などの様々な分野で活用が進められている。\n㋒　SAF（持続可能な航空燃料）とは、廃食油、バイオマス燃料、廃プラスチックなどを用いて生産される航空燃料のことである。従来のジェット燃料よりも二酸化炭素の排出量を削減できるほか、製造コストも低いため、我が国は、2030年時点で本邦航空会社による燃料使用量の60％をSAFに置き換えるという目標を掲げている。",
