    "question": "次の記述の空欄に当てはまるものとして最も妥当なのはどれか。\n\n「1 molの気体についてのファンデルワールスの状態方程式は以下のようである。\n\n(p＋a／vₘ²)(vₘ−b)＝RT\n\nここで、pは圧力、vₘはモル体積、Rは気体定数、Tは絶対温度、a、bはファンデルワールス定数である。\nファンデルワールスの状態方程式に従う気体分子を半径rの球とすると、隣り合う2分子は体積(32／3)πr³の空間より内側に侵入できない。\nプロパン分子を球とみなすとき、ファンデルワールスの状態方程式に従うプロパン分子のrは［　］mとなる。ただし、プロパン分子のaを0.88 Pa・m⁶・mol⁻²、bを8.5×10⁻⁵ m³・mol⁻¹とし、アボガドロ定数を6.0×10²³ mol⁻¹とする。」",
