    "question": "信号計測に関する記述㋐～㋓のうち、妥当なもののみを挙げているのはどれか。\n㋐　独立事象を離散的に計測した結果を基に、信号に対する雑音の割合を、半分程度に減少させるために、追加計測を実施して採取データ数の合計が2倍以上になるようにした。\n㋑　離散データに非線形関数を当てはめる際に最小二乗法が利用できるが、逐次反復計算によって解を収束させる必要があり、信頼性のある収束解を得るには初期値の適切な設定も必要である。\n㋒　周期性のある信号の離散計測において、データ量の軽減のため測定時間の間隔を広げる際に、信号1周期分相当の時間を間隔の上限として設定すればよい。\n㋓　実時間で計測したデータから必要な信号と雑音を分離する場合に、周波数スペクトルでの解析が有効な場合がある。離散データの周波数解析には、高速フーリエ変換などが利用できる。",
