    "question": "ガンマ線検出器に関する次の記述の㋐、㋑、㋒に当てはまるものの組合せとして最も妥当なのはどれか。\n\n「ゲルマニウム検出器は、ガンマ線の検出に広く用いられている。ゲルマニウム検出器は、半導体検出器の一種であり、ダイオード特性を持たせたゲルマニウム単結晶から成る。ダイオードとして電流が流れない方向に電圧を印加して使用する。ゲルマニウム単結晶中にガンマ線が入射すると、［㋐］等の相互作用を通してゲルマニウム単結晶にエネルギーが付与され、その結果、多数の電子－［㋑］対が生成する。電子と［㋑］が電極に移動することで、電流パルスが信号として観測される。電子－［㋑］対の数は入射ガンマ線が付与したエネルギーに比例するため、電子又は［㋑］の電荷総量からガンマ線のエネルギーを算出することができる。\nもう一つの代表的なガンマ線検出器としてタリウム活性化ヨウ化ナトリウム検出器（NaI(Tl)検出器）が挙げられる。NaI(Tl)検出器は、シンチレーション検出器の一種であり、シンチレーションと呼ばれる放射線による発光現象を利用する。NaI(Tl)検出器は、シンチレーション物質としてヨウ化ナトリウムの単結晶に少量のタリウムを添加したものを使用する。発生したシンチレーション光は、［㋒］等の光検出器を用いて電気信号に変換される。シンチレーションによる光子数は、入射ガンマ線の付与エネルギーに比例するため、発生光子数からガンマ線エネルギーを知ることができる。」",
