    "question": "図のように、水路勾配が滑らかに変化する一様な広矩形断面水路がある。流れが常流から射流に変化する際の水深、水路勾配及び水面勾配に関する次の記述の㋐、㋑、㋒に当てはまるものの組合せとして最も妥当なのはどれか。\nただし、水深をh、単位幅当たりの流量をq、水路勾配をi、シェジーの係数をC、エネルギー補正係数をα、水路床に沿う流下方向座標をx、重力加速度の大きさをgとするとき、不等流の基礎式は次式で与えられる。\n\n−[αq²／(gh³)] dh／dx＝i−dh／dx−q²／(C²h³)\n\n「不等流の基礎式から、支配断面（x＝x꜀）における水深は、h＝∛(αq²／g)≡h꜀となる。また、このときの水路勾配はi＝［㋐］≡i꜀で与えられる。ここで、h꜀、i꜀はそれぞれ支配断面におけるh、iの値である。さらに、支配断面における水面勾配hₓ꜀は、不等流の基礎式をxで微分することにより得られ、\n\n［㋑］ hₓ꜀²＝iₓ꜀＋［㋒］ hₓ꜀\n\nを満たす。ここで、hₓ꜀、iₓ꜀は、それぞれ支配断面におけるdh／dx及びdi／dxの値である。」",
