      "イ": "g／(αC²) ／ αq²／(gh꜀³) ／ q²／(C²h꜀³)",
      "ウ": "g／(αC²) ／ 3αq²／(gh꜀⁴) ／ 3q²／(C²h꜀⁴)",
      "エ": "αg／C² ／ −αq²／(gh꜀³) ／ q²／(C²h꜀³)",
