    "explanation": "h꜀³＝αq²／gではdh／dxの係数が0になり、i꜀＝q²／(C²h꜀³)＝g／(αC²)となる。整理した式(1−αq²／(gh³))h′＝i−q²／(C²h³)を微分すると、支配断面で左に3αq²h′²／(gh꜀⁴)、右にi′＋3q²h′／(C²h꜀⁴)が残る。",
