    "difficulty": 3,
    "question": "図のような、質点（質量m）と水平ばね（水平剛性k_H）が回転ばね（回転剛性k_R）で支えられている系の非減衰自由振動を考える。この系の固有周期として最も妥当なのはどれか。\nただし、ばね変形は微小で弾性の範囲内とし、系は水平方向のみ1自由度とする。また、重力の影響は無視する。\nなお、質点に微小な水平力Pを加えたとき、その水平変位は、水平ばねによる寄与P／k_Hと回転ばねによる寄与Ph²／k_Rの和で表される。",
