    "question": "我が国の鉄骨造建築物の構造設計に関する記述㋐～㋓のうち、妥当なもののみを挙げているのはどれか。\n㋐　大地震時に、炭素鋼の筋かいに必要な塑性変形能力を発揮させるためには、筋かいの端部及び接合部の破断耐力を、筋かい軸部の降伏耐力の1.2倍以上確保する必要がある。\n㋑　部材の塑性変形能力を確保するために定められているH形鋼の幅厚比の上限値は、フランジよりウェブの方が小さくなる。\n㋒　圧縮材の許容圧縮応力度の算定に用いる限界細長比は、SN400よりもSN490を用いた方が大きくなる。\n㋓　高力ボルトの許容せん断応力度は、摩擦接合としての許容応力度を意味し、すべり耐力に基づいて決められている。",
