    "difficulty": 3,
    "question": "我が国の建築物におけるガラス工事に関する記述㋐～㋓のうち、妥当なもののみを挙げているのはどれか。\n㋐　強化ガラスは、割れたときに、破片が尖らず粒状になって安全であるが、成形後に切断などの加工はできない。\n㋑　網入板ガラスは、網封入により熱割れを生じる可能性が低く、火災時の延焼防止用として使用される。\n㋒　複層ガラスは、一般に、平行配置した2枚以上の板ガラスの中空部に完全乾燥空気を封入したガラスであり、断熱性や防露性に優れる。\n㋓　Low-Eガラス（低放射ガラス）は、板ガラスの表面に特殊金属膜を形成したものであるため、複層ガラスとして使用できない。",
