    "question": "国際単位系（SI）では、次元的に独立であるとみなされる次の①～⑦に示す七つの量を基本単位として選定している。\n①長さ：メートル［m］、②質量：キログラム［kg］、③時間：秒［s］、④電流：アンペア［A］、⑤熱力学温度：ケルビン［K］、⑥物質量：モル［mol］、⑦光度：カンデラ［cd］\n国際単位系（SI）に関する次の記述の㋐～㋔に当てはまるものの組合せとして最も妥当なのはどれか。\n・キログラム（記号はkg）は、質量のSI単位であり、［㋐］を単位J s（kg m² s⁻¹に等しい）で表したときに、その数値を6.62607015×10⁻³⁴と定めることによって定義される。\n・アンペア（記号はA）は、電流のSI単位であり、電気素量eを単位C（A sに等しい）で表したときに、その数値を［㋑］と定めることによって定義される。\n・ケルビン（記号はK）は、熱力学温度のSI単位であり、［㋒］を単位J K⁻¹（kg m² s⁻² K⁻¹に等しい）で表したときに、その数値を1.380649×10⁻²³と定めることによって定義される。\n・モル（記号はmol）は、物質量のSI単位であり、1モルには、厳密に［㋓］個の要素粒子が含まれる。この数は、［㋔］を単位mol⁻¹で表したときの数値である。",
