      "ウ": "断熱充填のエネルギー収支では、流入気体の単位質量当たりのエンタルピーCₚT₀が容器内の内部エネルギーCᵥTに移るため、公式正答はκT₀となる。ただし、等圧の外気と最終気体の比エントロピーを比較するとCₚ ln κだけ増えるので、両者の比エントロピーが等しいという解釈はこの充填モデルと両立しない。",
