    "difficulty": 3,
    "question": "音環境に関する次の記述の㋐～㋓に当てはまるものの組合せとして最も妥当なのはどれか。\n・全ての方向に均等に音を放射している無指向性の点音源が二つ同時に存在し、音の強さのレベルがそれぞれ60 dBであるとき、それらを合成した音の強さのレベルは約［㋐］dBとなる。\nなお、音の強さのレベルとは、物理量である音の強さIを感覚量Lで表したものであり、1000 Hzの純音を聞き取れる最低の音の強さI₀＝10⁻¹² W/m²を用いて、L＝10 log₁₀(I／I₀)［dB］とレベル表示される。また、log₁₀2≒0.3010である。\n・一つの点音源から任意の距離r₁離れた点における音の強さのレベルL₁は、音源のパワーレベルをL_Wとすると、L₁＝L_W−10 log₁₀(r₁²)−11［dB］で表される。点音源からの鉛直距離が2倍（r₁から2r₁）になると、音の強さのレベルは約［㋑］dB減少する。\n・音源には、点音源のほかに、線音源や面音源がある。\n線音源とは、音が線状に放射されるような音源のことで、音源と平行な向きへのエネルギー拡散がないため、エネルギー密度は鉛直距離に反比例する。例えば、一列に並んだ窓から放射される室内発生音や交通量の多い道路は、線音源とみなすことができる。\n面音源とは、面全体から音が放射されるような音源のことで、無限大の面積の面音源は、音のエネルギー密度が変化せずに伝搬するとみなせるので、距離が離れても減衰することはない。例えば、工場内の音が大きな壁面全体を通して外に聞こえる場合は、面音源とみなすことができる。\n短辺がa［m］、長辺がb［m］の有限面の音源の場合、観測者と音源との距離がa／π以下のときは面音源とみなし、a／πより遠くなると［㋒］、さらにb／πより遠くなると［㋓］と同じように扱う。",
