    "question": "空気調和設備のダクトに関する次の記述の㋐、㋑、㋒に当てはまるものの組合せとして最も妥当なのはどれか。\n\n「円形ダクトの直管の摩擦抵抗による圧力損失は、管の直径に［㋐］する。円形ダクトと長方形ダクトでは、同じ断面積の場合、一般に［㋑］の方が抵抗は少なく、効率も良い。また、長方形ダクトにおいて同一風量の場合、ダクトの断面積を一定としたまま、その断面の短辺に対する長辺の比を大きくすると、圧力損失は［㋒］する。\nなお、長方形ダクトは、長辺と短辺の長さによって抵抗が変わるが、同一風量を流したときに同じ摩擦係数を示す円形ダクトの相当直径deは、長方形断面辺長をa、bとすると、\n\nde＝1.3×(ab)^(5／8)／(a＋b)^(1／4)\n\nと表される。」",
