    "difficulty": 3,
    "question": "我が国の都市計画に関する記述㋐～㋓のうち、妥当なもののみを挙げているのはどれか。\n㋐　都市計画区域マスタープランにおいて定める事項として都市計画法に規定されているのは、(1)都市計画の目標、(2)区域区分の決定の有無と、区域区分を定める場合はその方針、(3)土地利用、都市施設の整備及び市街地開発事業に関する主要な都市計画の決定の方針、(4)都市計画事業の財源の方針、の4点である。\n㋑　都市計画法における区域区分制度とは、都市計画区域について市街化区域と市街化調整区域とに区分し、それぞれの区域の性格に即した開発規制を課す仕組みである。市街化区域には、用途地域及び都市施設（道路、公園及び下水道）を定めるほか、市街地開発事業を必要に応じて定める。\n㋒　都市公園法における都市公園とは、国や地方公共団体が都市計画区域内に計画・整備する公園であり、住区基幹公園、都市基幹公園等の種類がある。住区基幹公園には、街区公園、近隣公園、地区公園があり、主として街区内に居住する者の利用に供することを目的とする街区公園は、誘致距離800 mの範囲内で1箇所当たり面積400 m²を標準として配置する。\n㋓　地方公共団体は、根幹的な都市施設を定める等の都市計画の決定について、都市計画の案を作成しようとする場合において必要があると認めるときは、公聴会の開催等住民の意見を反映させるために必要な措置を講ずる。",
