    "question": "規則波中を航行する船舶に関する次の記述の㋐、㋑、㋒に当てはまるものの組合せとして最も妥当なのはどれか。\n\n「ある船が船速Vで、波長λ、波の位相速度cの規則波中を直進している。水深が十分深いところでの規則波の位相速度は［㋐］である。\nただし、gは重力加速度の大きさである。\nいま、船の進行方向と波の進行方向のなす角をχとし、向波をχ＝180°、追波をχ＝0°として定義する。このとき、船と波の出会い周期は［㋑］で表される。また、出会い周期が最小となる波向きは［㋒］となる。」",
